import numpy as np
from scipy.optimize import minimize_scalar

def h(z):
    # h(z) = 5/2 z - 9/2 z^3 - 4 * sqrt((1 - z^2)/2)
    # Constraint: -1 <= z <= 1
    if abs(z) > 1:
        return float('inf')

    x_squared = (1 - z**2) / 2
    if x_squared < 0:
        return float('inf')

    return 2.5 * z - 4.5 * z**3 - 4 * np.sqrt(x_squared)

# Minimize h(z) in the interval [-1, 1]
result = minimize_scalar(h, bounds=(-1, 1), method='bounded')
print(f"Minimum value: {result.fun}")
print(f"Minimum z value: {result.x}")

